				\usepackage{upgreek}
				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$$Q = \sum\limits_{i = 1}^{n} {\sum\limits_{j = 1}^{m} {\left[ {\frac{{{\text{ x}}_{{{\mathrm{ij}}}} - \sum\limits_{k = 1}^{p} {g_{ik} } f_{jk} }}{{u_{ij} }}} \right]} }^{2}$$\end{document}\documentclass[12pt]{minimal}
